@partial(jit, static_argnums=0)        
def Qisa(self,
          Xisa:jnp.ndarray, # Joint strategy
          ) -> jnp.ndarray:  # Average state-action values
    """
    Compute Q-value for state `s` and action `a`.
    """
    Qisaq = self.Qisaq(Xisa)  # Q-return distrib
    gpoints = jnp.ones((self.nr)) * -1
    gpoints = gpoints.at[:].set(self.gridpoints)
    Qisa = jnp.einsum('ijkl,l->ijk', Qisaq, gpoints)
    i = 0; a = 1; s = 2
    Qis = jnp.einsum(Qisa, [i, s, a], Xisa, [i, s, a], [i, s])  # baseline
    # Baseline: mean of Qisaq
    Qis_expanded = jnp.expand_dims(Qis, axis=2)  # shape (N, Z, 1)
    baseline = jnp.repeat(Qis_expanded, self.M, axis=2)  # shape (N, Z, M)
    if self.method=='mean':  # take mean
        return Qisa
    elif self.method=='quantile':  # use quantile
        return quantile(self.tau, Qisaq, gpoints)
    elif self.method=='expectile':  # use expectile
        return expectile(self.tau, Qisaq, gpoints)
    elif self.method=='weights':  # use weights
        w = jnp.ones((self.N, self.Z, self.M, len(self.gridpoints)))
        n = jnp.newaxis
        upper = self.gridpoints[n,n,n,:] >= baseline[:,:,:,n]
        upper = upper * (self.wU - 1)
        w = w + upper
        wQisaq = weights(w, Qisaq, gpoints)
        Qisa = jnp.einsum('ijkl,l->ijk', wQisaq, gpoints)  # take the new distrib's mean
        return Qisa

DDRLSarsa.Qisa = Qisa 

# %% ../../nbs/02.02_DDRLSarsa.ipynb #40ac11e7
@partial(jit, static_argnums=(0,2))
def TDerror(self:DDRLSarsa,
            Xisa,  # Behavior profiles
            norm=False) -> jnp.ndarray:
    """
    Compute reward-prediction/temporal-difference error for 
    strategy SARSA dynamics, given joint strategy `Xisa`.
    """
    Q = self.Qisa(Xisa)
    n = jnp.newaxis
    E = Q - (1 / self.beta[:,n,n]) * jnp.log(Xisa)
    E *= self.beta[:,n,n]
    
    E = E - E.mean(axis=2, keepdims=True) if norm else E
    return E

DDRLSarsa.TDerror = TDerror
